changeSet.sql:
UPDATE "${schema}".asset SET asset_tag = NULLIF(BTRIM(asset_tag), ''), serial_number = NULLIF(BTRIM(serial_number), ''), status = CASE WHEN UPPER(BTRIM(status)) IN ('AVAILABLE', 'ASSIGNED', 'RETIRED') THEN UPPER(BTRIM(status)) WHEN EXISTS ( SELECT 1 FROM "${schema}".asset_allocation allocation WHERE allocation.tenant_id = asset.tenant_id AND allocation.asset_id = asset.id AND allocation.status = 'ACTIVE' ) THEN 'ASSIGNED' ELSE 'AVAILABLE' END;
ALTER TABLE "${schema}".asset ADD CONSTRAINT chk_asset_status CHECK (status IN ('AVAILABLE', 'ASSIGNED', 'RETIRED'));
ALTER TABLE "${schema}".asset_category ADD CONSTRAINT chk_asset_category_name_not_blank CHECK (length(BTRIM(name)) > 0);
ALTER TABLE "${schema}".asset ADD CONSTRAINT chk_asset_name_not_blank CHECK (length(BTRIM(name)) > 0), ADD CONSTRAINT chk_asset_purchase_value_non_negative CHECK (purchase_value IS NULL OR purchase_value >= 0);
CREATE UNIQUE INDEX uq_asset_tenant_asset_tag_ci ON "${schema}".asset (tenant_id, UPPER(asset_tag)) WHERE asset_tag IS NOT NULL AND BTRIM(asset_tag) <> '';
CREATE UNIQUE INDEX uq_asset_tenant_serial_number_ci ON "${schema}".asset (tenant_id, UPPER(serial_number)) WHERE serial_number IS NOT NULL AND BTRIM(serial_number) <> '';
CREATE UNIQUE INDEX uq_asset_return_log_allocation ON "${schema}".asset_return_log (tenant_id, asset_allocation_id);

rollback.sql:
DROP INDEX IF EXISTS "${schema}".uq_asset_return_log_allocation;
DROP INDEX IF EXISTS "${schema}".uq_asset_tenant_serial_number_ci;
DROP INDEX IF EXISTS "${schema}".uq_asset_tenant_asset_tag_ci;
ALTER TABLE "${schema}".asset DROP CONSTRAINT IF EXISTS chk_asset_purchase_value_non_negative;
ALTER TABLE "${schema}".asset DROP CONSTRAINT IF EXISTS chk_asset_name_not_blank;
ALTER TABLE "${schema}".asset_category DROP CONSTRAINT IF EXISTS chk_asset_category_name_not_blank;
ALTER TABLE "${schema}".asset DROP CONSTRAINT IF EXISTS chk_asset_status;
